# 课文 沙漠中的饭店 — 12 догол мөр (номын х.27-29 + х.30 эхлэл, PDF х.43-46). tokens "|"-ээр; (tokens, mn, note|None, key_structures[])
# Анхаар: өгүүлбэр бүрийг энгийн текстээр бичиж, tok() ньfunction үгсийн жагсаалтаар (vocab + META.extra_words) хамгийн урт таарцаар токенд хуваана.
import re
from meta import META
from vocab import VOCAB
SOURCE_NOTE = "(сурах бичгийн х.27-30, PDF х.43-46; 选自《撒哈拉的故事》, зохиолч 三毛; 脚注 ①荷西 ②壮士一去不复返 ③孙悟空)"
_W = set(META["extra_words"]) | {z.split("（")[0] for z, *_ in VOCAB} | {"撒哈拉的故事"}
_W = {w for w in _W if len(w) > 1}
_M = max(len(w) for w in _W)
_P2 = ["……", "——"]
_PUN = set("，。！？：；、（）…—")
def tok(zh):
    out, i, pend = [], 0, ""
    while i < len(zh):
        c = zh[i]
        if c in "“‘《": pend += c; i += 1; continue
        if c in "”’》": out[-1] += c; i += 1; continue
        if zh[i:i+2] in _P2: out.append(pend + zh[i:i+2]); pend = ""; i += 2; continue
        if c in _PUN: out.append(pend + c); pend = ""; i += 1; continue
        if re.match(r"[0-9A-Za-z]", c):
            m = re.match(r"[0-9A-Za-z]+", zh[i:]).group(0); out.append(pend + m); pend = ""; i += len(m); continue
        for L in range(min(_M, len(zh) - i), 1, -1):
            w = zh[i:i+L]
            if w in _W and not any(ch in "，。！？：；、“”《》" for ch in w): out.append(pend + w); pend = ""; i += L; break
        else: out.append(pend + c); pend = ""; i += 1
    return "|".join(out)
def S(zh, mn, note=None, ks=None): return (tok(zh), mn, note, ks or [])


